 import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, color as nodeColor, smoothstep, length } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, PointLight, LineSegments, LineBasicMaterial, EdgesGeometry, DoubleSide, Color, Vector3, Box3 } = THREE;

  const palette = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const ink = nodeColor(palette.ink || '#16161d');
  const surface = nodeColor(palette.surface || '#0b0b10');
  const accentC = new Color(palette.accent || '#ff2a38');

  const root = new Group();
  root.userData.isInteractive = true;
  root.userData.handlers = {};

  const timelines = [];
  const fxCleanups = [];

  const cardW = 2.2;
  const cardH = 1.4;
  const cardD = 0.08;

  const cardGeo = new BoxGeometry(cardW, cardH, cardD, 32, 32, 2);

  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(palette.surface || '#0b0b10'),
    metalness: 0.5,
    roughness: 0.6,
    clearcoat: 0.15,
    clearcoatRoughness: 0.4,
    anisotropy: 0.4,
    side: DoubleSide,
  });
  cardMat.colorNode = mix(surface, ink, uv().y);

  const card = new Mesh(cardGeo, cardMat);
  root.add(card);

  const edgeGeo = new EdgesGeometry(cardGeo);
  const edgeMat = new LineBasicMaterial({ color: accentC, transparent: true, opacity: 0 });
  const edge = new LineSegments(edgeGeo, edgeMat);
  root.add(edge);

  const shadowGeo = new PlaneGeometry(1.6, 1.6);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const shadowU = length(uv().sub(vec2(0.5, 0.5)));
  shadowMat.colorNode = vec4(vec3(0.0), smoothstep(0.5, 0.0, shadowU).mul(0.5));

  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.9, 0);
  root.add(shadow);

  const rim = new PointLight(accentC, 0.85, 7.0);
  rim.position.set(1.2, 0.8, 1.4);
  root.add(rim);

  const fill = new PointLight(new Color(palette.paper || '#e8ecf2'), 0.55, 7.0);
  fill.position.set(-1.2, -0.5, 1.4);
  root.add(fill);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (!gltf?.scene) return;

      const scene = gltf.scene;
      const box = new Box3().setFromObject(scene);
      const size = new Vector3();
      box.getSize(size);
      const maxDim = Math.max(size.x, size.y, size.z) || 1;

      const targetH = 1.0;
      const s = targetH / maxDim;
      scene.scale.setScalar(s);

      const center = new Vector3();
      box.getCenter(center);
      scene.position.sub(center.clone().multiplyScalar(s));
      scene.position.z += cardD / 2 + 0.06;

      root.add(scene);
    });
  }

  function killTracked() {
    timelines.forEach((t) => { try { t.kill(); } catch (e) {} });
  }

  function lift(active) {
    killTracked();
    const t = gsap.to(root.position, {
      z: active ? 0.15 : 0,
      duration: 0.35,
      ease: 'power2.out',
    });
    timelines.push(t);
  }

  function press(active) {
    killTracked();
    const s = active ? 0.97 : 1.0;
    const t = gsap.to(root.scale, {
      x: s,
      y: s,
      z: s,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    timelines.push(t);
  }

  function focus(active) {
    gsap.to(edgeMat, {
      opacity: active ? 1 : 0,
      duration: 0.2,
      overwrite: true,
    });
  }

  const onPointerOver = () => lift(true);
  const onPointerOut = () => lift(false);

  root.userData.handlers.hover = onPointerOver;
  root.userData.handlers.pointerover = onPointerOver;
  root.userData.handlers.pointerout = onPointerOut;

  root.userData.handlers.click = () => {
    press(true);
    ctx.emit('hub-home.select', { source: config.id || 'stat-tile' });
    setTimeout(() => press(false), 150);
  };

  root.userData.handlers.focus = () => focus(true);
  root.userData.handlers.blur = () => focus(false);

  const primitives = config.cinematicPrimitives || [];
  for (const p of primitives) {
    if (ctx.primitives?.[p.name]) {
      const result = ctx.primitives[p.name](root, p.params || {});
      if (result?.cleanup) fxCleanups.push(result.cleanup);
    }
  }

  root.userData.cleanup = () => {
    killTracked();
    fxCleanups.forEach((fn) => { try { fn(); } catch (e) {} });
    cardMat.dispose();
    cardGeo.dispose();
    edgeMat.dispose();
    edgeGeo.dispose();
    shadowMat.dispose();
    shadowGeo.dispose();
  };

  return root;
}
